# ==============================================================================
# SAVE EVALUATION TESTS
# ==============================================================================

def test_save_evaluation_success(sample_gd_result):
    """Test saving a complete GD evaluation structure."""
    mock_collection = MagicMock()
    
    # When get_evaluation is called internally after update_one, find_one returns the doc with _id
    stored_doc = sample_gd_result.copy()
    stored_doc["_id"] = "mongo_oid_12345"
    stored_doc["document_type"] = "gd_evaluation"
    stored_doc["created_at"] = datetime.now(timezone.utc)
    stored_doc["updated_at"] = datetime.now(timezone.utc)
    mock_collection.find_one.return_value = stored_doc

    with patch.object(gd_repo, "collection", mock_collection):
        saved = gd_repo.save_evaluation(sample_gd_result)

    assert mock_collection.update_one.called
    filter_arg, update_arg = mock_collection.update_one.call_args[0]
    kwargs = mock_collection.update_one.call_args[1]

    assert filter_arg == {"session_id": "GD-SESSION-101"}
    assert kwargs.get("upsert") is True
    assert "$set" in update_arg
    assert "$setOnInsert" in update_arg
    assert update_arg["$set"]["document_type"] == "gd_evaluation"
    assert update_arg["$set"]["topic"] == sample_gd_result["topic"]
    assert update_arg["$set"]["session_duration"] == sample_gd_result["session_duration"]
    assert update_arg["$set"]["group_transcript"] == sample_gd_result["group_transcript"]
    assert update_arg["$set"]["final_scores"] == {"P1": 7.75, "P2": 8.00}

    # Verify return value has _id popped and all fields intact
    assert saved["session_id"] == "GD-SESSION-101"
    assert "_id" not in saved
    assert saved["document_type"] == "gd_evaluation"
    assert saved["final_scores"]["P1"] == 7.75


def test_save_evaluation_validation_errors():
    """Test validation when saving invalid evaluation payloads."""
    mock_collection = MagicMock()
    with patch.object(gd_repo, "collection", mock_collection):
        # Non-dict
        with pytest.raises(ValueError, match="must be a dictionary"):
            gd_repo.save_evaluation(["not", "a", "dict"])  # type: ignore[arg-type]

        # Missing session_id
        with pytest.raises(ValueError, match="session_id is required"):
            gd_repo.save_evaluation({"topic": "AI without session_id"})

        # Empty session_id
        with pytest.raises(ValueError, match="session_id is required"):
            gd_repo.save_evaluation({"session_id": "   ", "topic": "AI"})

    assert not mock_collection.update_one.called


def test_save_evaluation_deterministic_upsert(sample_gd_result):
    """Test that saving twice uses upsert and does not create duplicates."""
    mock_collection = MagicMock()
    stored_doc = sample_gd_result.copy()
    stored_doc["_id"] = "mongo_oid_12345"
    mock_collection.find_one.return_value = stored_doc

    with patch.object(gd_repo, "collection", mock_collection):
        # First save
        gd_repo.save_evaluation(sample_gd_result)
        # Second save (update)
        sample_gd_result["topic"] = "Updated Topic Name"
        gd_repo.save_evaluation(sample_gd_result)

    assert mock_collection.update_one.call_count == 2
    # Both calls must use upsert=True with filter by session_id
    for call in mock_collection.update_one.call_args_list:
        assert call[0][0] == {"session_id": "GD-SESSION-101"}
        assert call[1].get("upsert") is True


