def test_get_evaluation_found(sample_gd_result):
    """Test retrieving an existing evaluation strips _id and preserves all fields."""
    mock_collection = MagicMock()
    doc_with_id = sample_gd_result.copy()
    doc_with_id["_id"] = "mongo_obj_id_999"
    doc_with_id["document_type"] = "gd_evaluation"
    mock_collection.find_one.return_value = doc_with_id

    with patch.object(gd_repo, "collection", mock_collection):
        result = gd_repo.get_evaluation("GD-SESSION-101")

    mock_collection.find_one.assert_called_once_with({"session_id": "GD-SESSION-101"})
    assert result is not None
    assert "_id" not in result
    assert result["session_id"] == "GD-SESSION-101"
    assert result["document_type"] == "gd_evaluation"
    assert result["participants"][0]["participant_id"] == "P1"


def test_get_evaluation_not_found():
    """Test retrieving a non-existent evaluation returns None."""
    mock_collection = MagicMock()
    mock_collection.find_one.return_value = None

    with patch.object(gd_repo, "collection", mock_collection):
        result = gd_repo.get_evaluation("NON-EXISTENT")

    mock_collection.find_one.assert_called_once_with({"session_id": "NON-EXISTENT"})
    assert result is None


def test_get_evaluation_invalid_input():
    """Test get_evaluation handles empty or invalid session_id gracefully."""
    mock_collection = MagicMock()
    with patch.object(gd_repo, "collection", mock_collection):
        assert gd_repo.get_evaluation("") is None
        assert gd_repo.get_evaluation(None) is None  # type: ignore[arg-type]

    assert not mock_collection.find_one.called


