def test_delete_evaluation_success():
    """Test successful deletion of an evaluation document."""
    mock_collection = MagicMock()
    mock_delete_result = MagicMock()
    mock_delete_result.deleted_count = 1
    mock_collection.delete_one.return_value = mock_delete_result

    with patch.object(gd_repo, "collection", mock_collection):
        deleted = gd_repo.delete_evaluation("GD-SESSION-101")

    mock_collection.delete_one.assert_called_once_with({"session_id": "GD-SESSION-101"})
    assert deleted is True


def test_delete_evaluation_not_found():
    """Test deleting a non-existent evaluation returns False."""
    mock_collection = MagicMock()
    mock_delete_result = MagicMock()
    mock_delete_result.deleted_count = 0
    mock_collection.delete_one.return_value = mock_delete_result

    with patch.object(gd_repo, "collection", mock_collection):
        deleted = gd_repo.delete_evaluation("NON-EXISTENT")

    mock_collection.delete_one.assert_called_once_with({"session_id": "NON-EXISTENT"})
    assert deleted is False


def test_delete_evaluation_invalid_input():
    """Test delete_evaluation with invalid input returns False without calling DB."""
    mock_collection = MagicMock()
    with patch.object(gd_repo, "collection", mock_collection):
        assert gd_repo.delete_evaluation("") is False
        assert gd_repo.delete_evaluation(None) is False  # type: ignore[arg-type]

