# LIST EVALUATIONS & ERROR PROPAGATION TESTS
# ==============================================================================

def test_get_all_evaluations(sample_gd_result):
    """Test listing all evaluations with cursor handling."""
    mock_collection = MagicMock()
    mock_cursor = [
        {"_id": "id1", "session_id": "S1", "topic": "T1"},
        {"_id": "id2", "session_id": "S2", "topic": "T2"},
    ]
    mock_collection.find.return_value.sort.return_value.limit.return_value = mock_cursor

    with patch.object(gd_repo, "collection", mock_collection):
        results = gd_repo.get_all_evaluations(limit=10)

    assert len(results) == 2
    assert results[0]["session_id"] == "S1"
    assert "_id" not in results[0]
    assert results[1]["session_id"] == "S2"
    assert "_id" not in results[1]


def test_mongodb_error_propagation(sample_gd_result):
    """Test that underlying PyMongo database errors are surfaced cleanly."""
    mock_collection = MagicMock()
    mock_collection.update_one.side_effect = PyMongoError("Connection timeout")

    with patch.object(gd_repo, "collection", mock_collection):
        with pytest.raises(PyMongoError, match="Connection timeout"):
            gd_repo.save_evaluation(sample_gd_result)
